CREATE TABLE vsla_groups (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), project_id UUID NOT NULL REFERENCES projects(id), group_code VARCHAR(60) NOT NULL, name VARCHAR(180) NOT NULL, state_id UUID REFERENCES states(id), lga_id UUID REFERENCES lgas(id), community_id UUID REFERENCES communities(id), facilitator_user_id UUID REFERENCES users(id), date_formed DATE, meeting_location TEXT, group_type VARCHAR(20) CHECK(group_type IN ('SUPERVISED','SELF_MANAGED')), status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','ONBOARDING','ACTIVE','SUSPENDED','CLOSED','ARCHIVED')), created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,group_code));
CREATE INDEX groups_project_status_idx ON vsla_groups(project_id,status); CREATE INDEX groups_state_idx ON vsla_groups(state_id); CREATE INDEX groups_lga_idx ON vsla_groups(lga_id); CREATE INDEX groups_facilitator_idx ON vsla_groups(facilitator_user_id); CREATE INDEX groups_created_idx ON vsla_groups(created_at);
